'use client'

import { useState, useTransition } from 'react'
import { toggleNotificationPreference } from './actions'

export default function Home() {
  const [isEnabled, setIsEnabled] = useState(true)
  const [isPending, startTransition] = useTransition()

  const handleToggle = () => {
    startTransition(async () => {
      const newPreference = await toggleNotificationPreference(isEnabled)
      setIsEnabled(newPreference)
    })
  }

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <p>Email Notifications</p>
        <button
          onClick={handleToggle}
          disabled={isPending}
          style={{
            padding: '8px 16px',
            backgroundColor: isEnabled ? '#22c55e' : '#ef4444',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: isPending ? 'wait' : 'pointer',
            opacity: isPending ? 0.6 : 1,
          }}
        >
          {isPending ? 'Updating...' : isEnabled ? 'Enabled' : 'Disabled'}
        </button>
      </div>
    </main>
  )
}
